section.programlisting:
#!/usr/bin/env python3
import json
import sys

with open(sys.argv[1], encoding="utf-8") as source:
    results = json.load(source)
if (results["schema"], results["version"], results["status"]) != ("org.geeqie.duplicates", 1, "ready"):
    raise SystemExit("No completed duplicate results")
for group in results["groups"]:
    print(group["id"], [member["path"] for member in group["members"]])
